  9→TSharedPtr<FSlateStyleSet> FTranslatorsStyle::StyleInstance = nullptr;
 10→
 11→FName FTranslatorsStyle::GetStyleSetName()
 12→{
 13→	static FName StyleSetName(TEXT("TranslatorsStyle"));
 14→	return StyleSetName;
 15→}
 16→
 17→void FTranslatorsStyle::Initialize()
 18→{
 19→	if (!StyleInstance.IsValid())
 20→	{
 21→		StyleInstance = Create();
 22→		FSlateStyleRegistry::RegisterSlateStyle(*StyleInstance);
 23→	}
 24→}
 25→
 26→void FTranslatorsStyle::Shutdown()
 27→{
 28→	if (StyleInstance.IsValid())
 29→	{
 30→		FSlateStyleRegistry::UnRegisterSlateStyle(*StyleInstance);
 31→		StyleInstance.Reset();
 32→	}
 33→}
