 51→TSharedRef<FSlateStyleSet> FTranslatorsStyle::Create()
 52→{
 53→	TSharedRef<FSlateStyleSet> Style = MakeShareable(new FSlateStyleSet(GetStyleSetName()));
 54→
 55→	// -------------------------------------------------------------------------
 56→	// Colors
 57→	// -------------------------------------------------------------------------
 58→
 59→	// Backgrounds
 60→	Style->Set("Color.Background",      FSlateColor(FLinearColor(0.02f, 0.02f, 0.05f, 0.98f)));
 61→	Style->Set("Color.BackgroundSolid",  FSlateColor(FLinearColor(0.02f, 0.02f, 0.05f, 1.0f)));
 62→
 63→	// Primary accent — cyan family
 64→	Style->Set("Color.Cyan",            FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 1.0f)));
 65→	Style->Set("Color.CyanDim",         FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 0.8f)));
 66→	Style->Set("Color.CyanFaint",       FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 0.9f)));
 67→
 68→	// Secondary accent — gold
 69→	Style->Set("Color.Gold",            FSlateColor(FLinearColor(1.0f, 0.8f, 0.2f, 1.0f)));
 70→
 71→	// Text hierarchy
 72→	Style->Set("Color.TextPrimary",     FSlateColor(FLinearColor(0.9f, 0.9f, 0.9f, 1.0f)));
 73→	Style->Set("Color.TextSecondary",   FSlateColor(FLinearColor(0.7f, 0.7f, 0.8f, 1.0f)));
 74→	Style->Set("Color.TextDim",         FSlateColor(FLinearColor(0.5f, 0.5f, 0.6f, 1.0f)));
 75→	Style->Set("Color.TextMuted",       FSlateColor(FLinearColor(0.4f, 0.4f, 0.5f, 1.0f)));
 76→
 77→	// Semantic colors
 78→	Style->Set("Color.Insight",         FSlateColor(FLinearColor(0.7f, 0.8f, 0.7f, 1.0f)));
 79→	Style->Set("Color.IncompleteGray",  FSlateColor(FLinearColor(0.3f, 0.3f, 0.3f, 0.5f)));
 80→
 81→	// Button states
 82→	Style->Set("Color.ButtonNormal",    FSlateColor(FLinearColor(0.1f, 0.1f, 0.15f, 1.0f)));
 83→	Style->Set("Color.ButtonHovered",   FSlateColor(FLinearColor(0.2f, 0.4f, 0.5f, 1.0f)));
 84→
 85→	// Question depth tiers
 86→	Style->Set("Color.DepthSurface",    FSlateColor(FLinearColor(0.5f, 0.8f, 0.5f, 1.0f)));
 87→	Style->Set("Color.DepthPatterns",   FSlateColor(FLinearColor(0.3f, 0.8f, 0.8f, 1.0f)));
 88→	Style->Set("Color.DepthFeelings",   FSlateColor(FLinearColor(1.0f, 0.5f, 0.45f, 1.0f)));
 89→	Style->Set("Color.DepthCore",       FSlateColor(FLinearColor(1.0f, 0.85f, 0.3f, 1.0f)));
 90→
 91→	// -------------------------------------------------------------------------
 92→	// Fonts (all use FCoreStyle default — DPI-aware, no hardcoded paths)
 93→	// -------------------------------------------------------------------------
 94→
 95→	Style->Set("Font.Title",            FCoreStyle::GetDefaultFontStyle("Bold",    56));
 96→	Style->Set("Font.Heading",          FCoreStyle::GetDefaultFontStyle("Bold",    36));
 97→	Style->Set("Font.Subtitle",         FCoreStyle::GetDefaultFontStyle("Regular", 18));
 98→	Style->Set("Font.Body",             FCoreStyle::GetDefaultFontStyle("Regular", 16));
 99→	Style->Set("Font.Question",         FCoreStyle::GetDefaultFontStyle("Regular", 24));
100→	Style->Set("Font.Option",           FCoreStyle::GetDefaultFontStyle("Regular", 18));
101→	Style->Set("Font.Progress",         FCoreStyle::GetDefaultFontStyle("Regular", 14));
102→	Style->Set("Font.Caption",          FCoreStyle::GetDefaultFontStyle("Regular", 12));
103→	Style->Set("Font.Small",            FCoreStyle::GetDefaultFontStyle("Regular", 11));
104→	Style->Set("Font.Insight",          FCoreStyle::GetDefaultFontStyle("Regular", 13));
105→
106→	return Style;
107→}
