  40→// === TICK ===
  41→
  42→void UTranslatorsBridgeSubsystem::Tick(float DeltaTime)
  43→{
  44→    // Polling for state file changes
  45→    PollTimer += DeltaTime;
  46→    if (PollTimer >= PollInterval)
  47→    {
  48→        PollTimer = 0.0f;
  49→
  50→        IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
  51→
  52→        // Check USD state file first
  53→        FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
  54→        if (PlatformFile.FileExists(*UsdFilePath))
  55→        {
  56→            FDateTime ModTime = PlatformFile.GetTimeStamp(*UsdFilePath);
  57→            if (ModTime > LastStateFileTime)
  58→            {
  59→                LastStateFileTime = ModTime;
  60→                bStateChangePending = true;
  61→                TimeSinceLastStateChange = 0.0f;
  62→            }
  63→        }
  64→        else
  65→        {
  66→            // Fall back to JSON state file
  67→            FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
  68→            if (PlatformFile.FileExists(*JsonFilePath))
  69→            {
  70→                FDateTime ModTime = PlatformFile.GetTimeStamp(*JsonFilePath);
  71→                if (ModTime > LastStateFileTime)
  72→                {
  73→                    LastStateFileTime = ModTime;
  74→                    bStateChangePending = true;
  75→                    TimeSinceLastStateChange = 0.0f;
  76→                }
  77→            }
  78→        }
  79→
  80→        // Check USD profile files
  81→        FString ProfilePath = GetBridgeFilePath(TEXT("cognitive_profile.usda"));
  82→        FString SubstratePath = GetBridgeFilePath(TEXT("cognitive_substrate.usda"));
  83→        for (const FString& Path : { ProfilePath, SubstratePath })
  84→        {
  85→            if (PlatformFile.FileExists(*Path))
  86→            {
  87→                FDateTime ModTime = PlatformFile.GetTimeStamp(*Path);
  88→                if (ModTime > LastUsdFileTime)
  89→                {
  90→                    LastUsdFileTime = ModTime;
  91→                    bUsdChangePending = true;
  92→                    TimeSinceLastUsdChange = 0.0f;
  93→                }
  94→            }
  95→        }
  96→    }
  97→
  98→    // Debounced state file processing
  99→    if (bStateChangePending)
 100→    {
 101→        TimeSinceLastStateChange += DeltaTime;
 102→        if (TimeSinceLastStateChange >= DebounceTime)
 103→        {
 104→            bStateChangePending = false;
 105→            ProcessStateFile();
 106→        }
 107→    }
 108→
 109→    // Debounced USD profile processing
 110→    if (bUsdChangePending)
 111→    {
 112→        TimeSinceLastUsdChange += DeltaTime;
 113→        if (TimeSinceLastUsdChange >= DebounceTime)
 114→        {
 115→            bUsdChangePending = false;
 116→            BridgeLog(TEXT("USD profile file changed"));
 117→            // Find which file changed and broadcast
 118→            FString ProfilePath = GetBridgeFilePath(TEXT("cognitive_profile.usda"));
 119→            FString SubstratePath = GetBridgeFilePath(TEXT("cognitive_substrate.usda"));
 120→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 121→            if (PlatformFile.FileExists(*ProfilePath))
 122→            {
 123→                OnUsdProfileUpdated.Broadcast(ProfilePath);
 124→            }
 125→            else if (PlatformFile.FileExists(*SubstratePath))
 126→            {
 127→                OnUsdProfileUpdated.Broadcast(SubstratePath);
 128→            }
 129→        }
 130→    }
 131→}
