 134→// === GAME FLOW ===
 135→
 136→void UTranslatorsBridgeSubsystem::StartGame()
 137→{
 138→    if (bIsActive)
 139→    {
 140→        BridgeLog(TEXT("Bridge already active"));
 141→        return;
 142→    }
 143→
 144→    BridgeLog(TEXT("========================================"));
 145→    BridgeLog(TEXT("TRANSLATORS BRIDGE SUBSYSTEM v2.1.0"));
 146→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
 147→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
 148→    BridgeLog(TEXT("========================================"));
 149→
 150→    // Ensure bridge directory exists
 151→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 152→    if (!PlatformFile.DirectoryExists(*BridgePath))
 153→    {
 154→        PlatformFile.CreateDirectory(*BridgePath);
 155→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
 156→    }
 157→
 158→    bIsActive = true;
 159→    SetState(ETranslatorsBridgeState::WaitingForBridge);
 160→
 161→    // Check for existing state files (Python may have started first)
 162→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 163→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
 164→
 165→    if (PlatformFile.FileExists(*UsdFilePath))
 166→    {
 167→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
 168→        ProcessStateFile();
 169→    }
 170→    else if (PlatformFile.FileExists(*JsonFilePath))
 171→    {
 172→        BridgeLog(TEXT("Found existing state.json - processing..."));
 173→        ProcessStateFile();
 174→    }
 175→}
 176→
 177→void UTranslatorsBridgeSubsystem::StopGame()
 178→{
 179→    if (!bIsActive)
 180→    {
 181→        return;
 182→    }
 183→
 184→    bIsActive = false;
 185→    bStateChangePending = false;
 186→    bUsdChangePending = false;
 187→    SetState(ETranslatorsBridgeState::Idle);
 188→
 189→    BridgeLog(TEXT("Bridge stopped"));
 190→}
