 193→void UTranslatorsBridgeSubsystem::SubmitAnswer(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 194→{
 195→    // Try USD mode first
 196→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 197→    FString Content;
 198→
 199→    if (bUsingUsdMode && FFileHelper::LoadFileToString(Content, *FilePath))
 200→    {
 201→        FString Timestamp = FDateTime::UtcNow().ToIso8601();
 202→        FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 203→            ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 204→        FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 205→            ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 206→
 207→        Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 208→        Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 209→
 210→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 211→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 212→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 213→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 214→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 215→        Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 216→
 217→        UpdateBehavioralSignals(Content, ResponseTimeMs);
 218→
 219→        int32 MaxRetries = 3;
 220→        for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 221→        {
 222→            if (FFileHelper::SaveStringToFile(Content, *FilePath))
 223→            {
 224→                BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 225→                    *QuestionId, OptionIndex, ResponseTimeMs));
 226→                SetState(ETranslatorsBridgeState::AnswerPending);
 227→                return;
 228→            }
 229→            FPlatformProcess::Sleep(0.1f);
 230→        }
 231→
 232→        BridgeLog(TEXT("USD answer write failed, falling back to JSON"));
 233→    }
 234→
 235→    // JSON fallback
 236→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 237→    JsonObj->SetStringField(TEXT("$schema"), TEXT("translators-answer-v1"));
 238→    JsonObj->SetStringField(TEXT("type"), TEXT("answer"));
 239→    JsonObj->SetStringField(TEXT("timestamp"), FDateTime::UtcNow().ToIso8601());
 240→
 241→    TSharedPtr<FJsonObject> AnswerObj = MakeShared<FJsonObject>();
 242→    AnswerObj->SetStringField(TEXT("question_id"), QuestionId);
 243→    AnswerObj->SetNumberField(TEXT("option_index"), OptionIndex);
 244→    AnswerObj->SetNumberField(TEXT("response_time_ms"), ResponseTimeMs);
 245→    JsonObj->SetObjectField(TEXT("answer"), AnswerObj);
 246→
 247→    WriteJsonToFile(TEXT("answer.json"), JsonObj);
 248→    SetState(ETranslatorsBridgeState::AnswerPending);
 249→
 250→    BridgeLog(FString::Printf(TEXT("JSON answer sent: %s = option %d (%.0fms)"),
 251→        *QuestionId, OptionIndex, ResponseTimeMs));
 252→}
