 255→void UTranslatorsBridgeSubsystem::SendAcknowledge()
 256→{
 257→    // Try USD mode first
 258→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 259→    FString Content;
 260→
 261→    if (FFileHelper::LoadFileToString(Content, *FilePath))
 262→    {
 263→        FString Timestamp = FDateTime::UtcNow().ToIso8601();
 264→
 265→        Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("ack"));
 266→        Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ready"), TEXT("true"), false);
 267→        Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ue_version"), FString(ENGINE_VERSION_STRING), true);
 268→        Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("project"), TEXT("TranslatorsCard"), true);
 269→        Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("timestamp"), Timestamp, true);
 270→
 271→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 272→        {
 273→            BridgeLog(TEXT("USD acknowledgment sent"));
 274→            bUsingUsdMode = true;
 275→            return;
 276→        }
 277→    }
 278→
 279→    // JSON fallback
 280→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 281→    JsonObj->SetStringField(TEXT("$schema"), TEXT("translators-answer-v1"));
 282→    JsonObj->SetStringField(TEXT("type"), TEXT("ack"));
 283→    JsonObj->SetStringField(TEXT("timestamp"), FDateTime::UtcNow().ToIso8601());
 284→
 285→    TSharedPtr<FJsonObject> AckObj = MakeShared<FJsonObject>();
 286→    AckObj->SetBoolField(TEXT("ready"), true);
 287→    AckObj->SetStringField(TEXT("ue_version"), FString(ENGINE_VERSION_STRING));
 288→    AckObj->SetStringField(TEXT("project"), TEXT("TranslatorsCard"));
 289→    JsonObj->SetObjectField(TEXT("ack"), AckObj);
 290→
 291→    WriteJsonToFile(TEXT("answer.json"), JsonObj);
 292→    BridgeLog(TEXT("JSON acknowledgment sent"));
 293→}
