 377→// === FILE I/O ===
 378→
 379→void UTranslatorsBridgeSubsystem::ProcessStateFile()
 380→{
 381→    // Try USD mode first (v2.0.0)
 382→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 383→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 384→
 385→    if (PlatformFile.FileExists(*UsdFilePath))
 386→    {
 387→        if (ProcessBridgeStateUsda())
 388→        {
 389→            return;
 390→        }
 391→    }
 392→
 393→    // Fall back to JSON mode (v1.0.0)
 394→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
 395→    FString Content;
 396→
 397→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 398→    {
 399→        return;
 400→    }
 401→
 402→    TSharedPtr<FJsonObject> JsonObj;
 403→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
 404→
 405→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
 406→    {
 407→        OnBridgeError.Broadcast(EBridgeErrorCode::JsonParseFailure, TEXT("Invalid JSON in state.json"));
 408→        return;
 409→    }
 410→
 411→    CurrentStateJson = Content;
 412→    bUsingUsdMode = false;
 413→
 414→    FString StateType;
 415→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
 416→    {
 417→        if (StateType == TEXT("ready"))
 418→        {
 419→            HandleReadyState(JsonObj);
 420→        }
 421→        else if (StateType == TEXT("question"))
 422→        {
 423→            HandleQuestionState(JsonObj);
 424→        }
 425→        else if (StateType == TEXT("transition"))
 426→        {
 427→            HandleTransitionState(JsonObj);
 428→        }
 429→        else if (StateType == TEXT("finale"))
 430→        {
 431→            HandleFinaleState(JsonObj);
 432→        }
 433→    }
 434→}
 435→
 436→
 437→void UTranslatorsBridgeSubsystem::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
 438→{
 439→    FString FilePath = GetBridgeFilePath(Filename);
 440→    FString OutputString;
 441→
 442→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 443→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 444→
 445→    int32 MaxRetries = 3;
 446→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 447→    {
 448→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
 449→        {
 450→            return;
 451→        }
 452→
 453→        if (Retry < MaxRetries - 1)
 454→        {
 455→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
 456→            FPlatformProcess::Sleep(0.1f);
 457→        }
 458→    }
 459→
 460→    OnBridgeError.Broadcast(EBridgeErrorCode::FileWriteFailure,
 461→        FString::Printf(TEXT("Failed to write %s after %d retries"), *Filename, MaxRetries));
 462→}
 463→
 464→
 465→// === JSON STATE HANDLERS ===
 466→
 467→void UTranslatorsBridgeSubsystem::HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj)
 468→{
 469→    const TSharedPtr<FJsonObject>* ReadyObjPtr;
 470→    const TSharedPtr<FJsonObject>& ReadyData =
 471→        JsonObj->TryGetObjectField(TEXT("ready"), ReadyObjPtr) ? *ReadyObjPtr : JsonObj;
 472→
 473→    int32 TotalQuestions = ReadyData->GetIntegerField(TEXT("total_questions"));
 474→
 475→    BridgeLog(FString::Printf(TEXT("Bridge ready! Total questions: %d"), TotalQuestions));
 476→
