 559→bool UTranslatorsBridgeSubsystem::ProcessBridgeStateUsda()
 560→{
 561→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 562→    FString Content;
 563→
 564→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 565→    {
 566→        return false;
 567→    }
 568→
 569→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 570→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 571→
 572→    if (bVerboseLogging)
 573→    {
 574→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 575→    }
 576→
 577→    if (MessageType == TEXT("ready"))
 578→    {
 579→        HandleUsdaReadyState(Content);
 580→    }
 581→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 582→    {
 583→        HandleUsdaQuestionState(Content);
 584→    }
 585→    else if (MessageType == TEXT("transition"))
 586→    {
 587→        HandleUsdaTransitionState(Content);
 588→    }
 589→    else if (MessageType == TEXT("finale"))
 590→    {
 591→        HandleUsdaFinaleState(Content);
 592→    }
 593→
 594→    return true;
