 598→FString UTranslatorsBridgeSubsystem::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 599→{
 600→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 601→    FRegexPattern RegexPattern(Pattern);
 602→    FRegexMatcher Matcher(RegexPattern, Content);
 603→
 604→    if (Matcher.FindNext())
 605→    {
 606→        return Matcher.GetCaptureGroup(1);
 607→    }
 608→    return TEXT("");
 609→}
