 611→
 612→FString UTranslatorsBridgeSubsystem::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 613→{
 614→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 615→    FRegexPattern PrimRegex(PrimPattern);
 616→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 617→
 618→    FString PrimContent;
 619→    if (PrimMatcher.FindNext())
 620→    {
 621→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 622→    }
 623→    else
 624→    {
 625→        PrimContent = Content;
 626→    }
 627→
 628→    // Parse string attribute
 629→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 630→    FRegexPattern StringRegex(StringPattern);
 631→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 632→    if (StringMatcher.FindNext())
 633→    {
 634→        return StringMatcher.GetCaptureGroup(1);
 635→    }
 636→
 637→    // Parse int attribute
 638→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 639→    FRegexPattern IntRegex(IntPattern);
 640→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 641→    if (IntMatcher.FindNext())
 642→    {
 643→        return IntMatcher.GetCaptureGroup(1);
 644→    }
 645→
 646→    // Parse float/double attribute
 647→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 648→    FRegexPattern FloatRegex(FloatPattern);
 649→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 650→    if (FloatMatcher.FindNext())
 651→    {
 652→        return FloatMatcher.GetCaptureGroup(1);
 653→    }
 654→
 655→    return TEXT("");
 656→}
