 762→FString UTranslatorsBridgeSubsystem::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 763→{
 764→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 765→    int32 StartIdx = Content.Find(SearchPattern);
 766→    if (StartIdx == INDEX_NONE)
 767→    {
 768→        return Content;
 769→    }
 770→
 771→    StartIdx += SearchPattern.Len();
 772→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 773→    if (EndIdx == INDEX_NONE)
 774→    {
 775→        return Content;
 776→    }
 777→
 778→    return Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 779→}
