 781→
 782→FString UTranslatorsBridgeSubsystem::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 783→{
 784→    FString Result = Content;
 785→
 786→    if (bIsString)
 787→    {
 788→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 789→        int32 StartIdx = Result.Find(SearchPattern);
 790→        if (StartIdx != INDEX_NONE)
 791→        {
 792→            StartIdx += SearchPattern.Len();
 793→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 794→            if (EndIdx != INDEX_NONE)
 795→            {
 796→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 797→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 798→            }
 799→        }
 800→    }
 801→    else
 802→    {
 803→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 804→
 805→        for (const FString& TypePrefix : TypePrefixes)
 806→        {
 807→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 808→            int32 StartIdx = Result.Find(SearchPattern);
 809→            if (StartIdx != INDEX_NONE)
 810→            {
 811→                StartIdx += SearchPattern.Len();
 812→                int32 EndIdx = StartIdx;
 813→                while (EndIdx < Result.Len())
 814→                {
 815→                    TCHAR C = Result[EndIdx];
 816→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 817→                    {
 818→                        break;
 819→                    }
 820→                    EndIdx++;
 821→                }
 822→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 823→                break;
 824→            }
 825→        }
 826→    }
 827→
 828→    return Result;
 829→}
