 832→// === BEHAVIORAL SIGNALS ===
 833→
 834→void UTranslatorsBridgeSubsystem::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 835→{
 836→    // Deterministic behavioral signal routing.
 837→    // Fixed thresholds ensure same signals produce same expert selection.
 838→
 839→    ResponseTimes.Add(ResponseTimeMs);
 840→
 841→    float TotalTime = 0.0f;
 842→    for (float Time : ResponseTimes)
 843→    {
 844→        TotalTime += Time;
 845→    }
 846→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 847→
 848→    // Fixed thresholds (deterministic across all sessions)
 849→    const float HESITATION_THRESHOLD_MS = 10000.0f;
 850→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;
 851→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f;
 852→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 853→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 854→
 855→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 856→    if (bLongHesitation)
 857→    {
 858→        Signals.HesitationCount++;
 859→    }
 860→
 861→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 862→    if (bRapidClick)
 863→    {
 864→        Signals.RapidClickCount++;
 865→    }
 866→
 867→    Signals.LastResponseTimeMs = ResponseTimeMs;
 868→    Signals.AverageResponseTimeMs = AvgResponseTime;
 869→    Signals.TotalResponsesRecorded = ResponseTimes.Num();
 870→
 871→    // ADHD_MoE fixed priority routing
 872→    FString DetectedState = TEXT("focused");
 873→    FString RecommendedExpert = TEXT("Direct");
 874→    FString BurnoutLevel = TEXT("GREEN");
 875→    FString MomentumPhase = TEXT("rolling");
 876→
 877→    if (Signals.RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 878→    {
 879→        DetectedState = TEXT("frustrated");
 880→        RecommendedExpert = TEXT("Validator");
 881→        BurnoutLevel = TEXT("RED");
 882→        MomentumPhase = TEXT("crashed");
 883→    }
 884→    else if (bLongHesitation || Signals.HesitationCount > HESITATION_COUNT_THRESHOLD)
 885→    {
 886→        DetectedState = TEXT("stuck");
 887→        RecommendedExpert = TEXT("Scaffolder");
 888→        BurnoutLevel = TEXT("ORANGE");
 889→        MomentumPhase = TEXT("declining");
 890→    }
 891→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 892→    {
 893→        DetectedState = TEXT("depleted");
 894→        RecommendedExpert = TEXT("Restorer");
 895→        BurnoutLevel = TEXT("ORANGE");
 896→        MomentumPhase = TEXT("crashed");
 897→    }
 898→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 899→    {
 900→        DetectedState = TEXT("distracted");
 901→        RecommendedExpert = TEXT("Refocuser");
 902→        BurnoutLevel = TEXT("YELLOW");
 903→        MomentumPhase = TEXT("declining");
 904→    }
 905→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 906→    {
 907→        DetectedState = TEXT("completing");
 908→        RecommendedExpert = TEXT("Celebrator");
 909→        BurnoutLevel = TEXT("GREEN");
 910→        MomentumPhase = TEXT("peak");
 911→    }
 912→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 913→    {
 914→        DetectedState = TEXT("exploring");
 915→        RecommendedExpert = TEXT("Socratic");
 916→        BurnoutLevel = TEXT("GREEN");
 917→        MomentumPhase = TEXT("building");
 918→    }
 919→    else
 920→    {
 921→        DetectedState = TEXT("focused");
 922→        RecommendedExpert = TEXT("Direct");
 923→        BurnoutLevel = TEXT("GREEN");
 924→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 925→    }
 926→
 927→    Signals.DetectedState = DetectedState;
 928→    Signals.RecommendedExpert = RecommendedExpert;
 929→    Signals.BurnoutLevel = BurnoutLevel;
 930→    Signals.MomentumPhase = MomentumPhase;
 931→
 932→    // Write signals into USD content
 933→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 934→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
 935→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("hesitation_count"), FString::FromInt(Signals.HesitationCount), false);
 936→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("long_hesitation_detected"), bLongHesitation ? TEXT("true") : TEXT("false"), false);
 937→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("rapid_click_count"), FString::FromInt(Signals.RapidClickCount), false);
 938→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("detected_state"), DetectedState, true);
 939→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("recommended_expert"), RecommendedExpert, true);
 940→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("burnout_level"), BurnoutLevel, true);
 941→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("momentum_phase"), MomentumPhase, true);
 942→
 943→    if (bVerboseLogging)
 944→    {
 945→        BridgeLog(FString::Printf(TEXT("[MoE] State=%s Expert=%s Burnout=%s Momentum=%s"),
 946→            *DetectedState, *RecommendedExpert, *BurnoutLevel, *MomentumPhase));
 947→    }
 948→}
