 966→// === COGNITIVE PROFILE PARSING ===
 967→
 968→FTranslatorsProfile UTranslatorsBridgeSubsystem::ParseCognitiveProfile(const FString& UsdPath)
 969→{
 970→    FTranslatorsProfile Profile;
 971→
 972→    FString Content;
 973→    if (!FFileHelper::LoadFileToString(Content, *UsdPath))
 974→    {
 975→        BridgeLog(FString::Printf(TEXT("Could not read profile: %s"), *UsdPath));
 976→        OnBridgeError.Broadcast(EBridgeErrorCode::ProfileParseFailure,
 977→            FString::Printf(TEXT("Cannot read %s"), *UsdPath));
 978→        return Profile;
 979→    }
 980→
 981→    BridgeLog(FString::Printf(TEXT("Parsing cognitive profile from: %s"), *UsdPath));
 982→    Profile.UsdExportPath = UsdPath;
 983→    Profile.GeneratorVersion = TEXT("2.1.0");
 984→
 985→    // Parse checksum
 986→    {
 987→        FRegexPattern Pattern(TEXT("string checksum = \"([^\"]*)\""));
 988→        FRegexMatcher Matcher(Pattern, Content);
 989→        if (Matcher.FindNext())
 990→        {
 991→            Profile.Checksum = Matcher.GetCaptureGroup(1);
 992→        }
 993→    }
 994→
 995→    // Parse anchor
 996→    {
 997→        FRegexPattern Pattern(TEXT("string anchor = \"([^\"]*)\""));
 998→        FRegexMatcher Matcher(Pattern, Content);
 999→        if (Matcher.FindNext())
1000→        {
1001→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1002→        }
1003→    }
1004→
1005→    // Parse anchor from customData (takes precedence)
1006→    {
1007→        FRegexPattern Pattern(TEXT("string translators_anchor = \"([^\"]*)\""));
1008→        FRegexMatcher Matcher(Pattern, Content);
1009→        if (Matcher.FindNext())
1010→        {
1011→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1012→        }
1013→    }
1014→
1015→    // Parse Profile dimensions
1016→    TMap<FString, float> DimensionScores;
1017→    TMap<FString, FString> TraitLabels;
1018→
1019→    {
1020→        int32 ProfileStart = Content.Find(TEXT("def Xform \"Profile\""));
1021→        if (ProfileStart != INDEX_NONE)
1022→        {
1023→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, ProfileStart);
1024→            if (BlockStart != INDEX_NONE)
1025→            {
1026→                int32 BraceDepth = 1;
1027→                int32 BlockEnd = BlockStart + 1;
1028→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1029→                {
1030→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1031→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1032→                    BlockEnd++;
1033→                }
1034→
1035→                FString ProfileBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1036→                FRegexPattern Pattern(TEXT("float (\\w+) = ([\\d.]+)"));
1037→                FRegexMatcher Matcher(Pattern, ProfileBlock);
1038→                while (Matcher.FindNext())
1039→                {
1040→                    FString Name = Matcher.GetCaptureGroup(1);
1041→                    float Value = FCString::Atof(*Matcher.GetCaptureGroup(2));
1042→                    DimensionScores.Add(Name, Value);
1043→                    Profile.Dimensions.Add(Name, Value);
1044→                }
1045→            }
1046→        }
1047→    }
1048→
1049→    // Parse Traits section
1050→    {
1051→        int32 TraitsStart = Content.Find(TEXT("def Xform \"Traits\""));
1052→        if (TraitsStart != INDEX_NONE)
1053→        {
1054→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, TraitsStart);
1055→            if (BlockStart != INDEX_NONE)
1056→            {
1057→                int32 BraceDepth = 1;
1058→                int32 BlockEnd = BlockStart + 1;
1059→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1060→                {
1061→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1062→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1063→                    BlockEnd++;
1064→                }
1065→
1066→                FString TraitsBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1067→                FRegexPattern Pattern(TEXT("string (\\w+) = \"([^\"]*)\""));
1068→                FRegexMatcher Matcher(Pattern, TraitsBlock);
1069→                while (Matcher.FindNext())
1070→                {
1071→                    TraitLabels.Add(Matcher.GetCaptureGroup(1), Matcher.GetCaptureGroup(2));
1072→                }
1073→            }
1074→        }
1075→    }
1076→
1077→    // Map question IDs to dimension names
1078→    TMap<FString, FString> QuestionToDimension;
1079→    QuestionToDimension.Add(TEXT("load"), TEXT("cognitive_density"));
1080→    QuestionToDimension.Add(TEXT("pace"), TEXT("processing_pace"));
1081→    QuestionToDimension.Add(TEXT("uncertainty"), TEXT("uncertainty_tolerance"));
1082→    QuestionToDimension.Add(TEXT("feedback"), TEXT("feedback_style"));
1083→    QuestionToDimension.Add(TEXT("recovery"), TEXT("home_altitude"));
1084→    QuestionToDimension.Add(TEXT("starting"), TEXT("guidance_frequency"));
1085→    QuestionToDimension.Add(TEXT("completion"), TEXT("default_paradigm"));
1086→    QuestionToDimension.Add(TEXT("essence"), TEXT("tangent_tolerance"));
1087→
1088→    // Build traits from combined data
1089→    for (const auto& Pair : TraitLabels)
1090→    {
1091→        FTranslatorsTrait Trait;
1092→        Trait.Label = Pair.Value;
1093→
1094→        FString* DimName = QuestionToDimension.Find(Pair.Key);
1095→        if (DimName)
1096→        {
1097→            Trait.Dimension = *DimName;
1098→            float* Score = DimensionScores.Find(*DimName);
1099→            Trait.Score = Score ? *Score : 0.5f;
1100→        }
1101→        else
1102→        {
1103→            Trait.Dimension = Pair.Key;
1104→            Trait.Score = 0.5f;
1105→        }
1106→
1107→        if (Trait.Score >= 0.7f)
1108→        {
1109→            Trait.Behavior = FString::Printf(TEXT("Strong %s tendency"), *Trait.Label);
1110→        }
1111→        else if (Trait.Score <= 0.3f)
1112→        {
1113→            Trait.Behavior = FString::Printf(TEXT("Measured %s approach"), *Trait.Label);
1114→        }
1115→        else
1116→        {
1117→            Trait.Behavior = FString::Printf(TEXT("Balanced %s style"), *Trait.Label);
1118→        }
1119→
1120→        Profile.Traits.Add(Trait);
1121→    }
1122→
1123→    // Generate insights
1124→    for (const FTranslatorsTrait& Trait : Profile.Traits)
1125→    {
1126→        if (Trait.Score >= 0.7f)
1127→        {
1128→            Profile.Insights.Add(FString::Printf(TEXT("High %s (%s) suggests strong preference in this dimension"),
1129→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1130→        }
1131→        else if (Trait.Score <= 0.3f)
1132→        {
1133→            Profile.Insights.Add(FString::Printf(TEXT("Low %s (%s) indicates a focused approach here"),
1134→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1135→        }
1136→    }
1137→
1138→    BridgeLog(FString::Printf(TEXT("Parsed profile: %d traits, %d insights, checksum=%s"),
1139→        Profile.Traits.Num(), Profile.Insights.Num(), *Profile.Checksum));
1140→
1141→    return Profile;
1142→}
