113→// === PYTHON PROCESS ===
114→
115→void UBridgeEditorSubsystem::StartBridgeProcess()
116→{
117→    if (bBridgeProcessRunning)
118→    {
119→        UE_LOG(LogTranslatorsBridge, Warning, TEXT("Bridge process already running"));
120→        return;
121→    }
122→
123→    // Locate bridge_orchestrator.py — project Scripts/ dir first, then user home fallback
124→    FString ScriptPath = FPaths::Combine(FPaths::ProjectDir(), TEXT("Scripts"), TEXT("bridge_orchestrator.py"));
125→    if (!IFileManager::Get().FileExists(*ScriptPath))
126→    {
127→        FString UserHome = FPlatformMisc::GetEnvironmentVariable(TEXT("USERPROFILE"));
128→        ScriptPath = FPaths::Combine(UserHome, TEXT(".translators"), TEXT("bridge_orchestrator.py"));
129→    }
130→
131→    if (!IFileManager::Get().FileExists(*ScriptPath))
132→    {
133→        UE_LOG(LogTranslatorsBridge, Warning,
134→            TEXT("Bridge script not found. Looked in ProjectDir/Scripts/ and %%USERPROFILE%%/.translators/. "
135→                 "Use Launch-TranslatorsBridge.ps1 for manual launch."));
136→        return;
137→    }
138→
139→    // Resolve Python executable
140→    const TCHAR* PythonExe = TEXT("python");
141→
142→    // Build command-line arguments (just the script path)
143→    FString Args = FString::Printf(TEXT("\"%s\""), *ScriptPath);
144→
145→    // Launch the process
146→    const bool bLaunchDetached = true;
147→    const bool bLaunchHidden = true;
148→    const bool bLaunchReallyHidden = false;
149→    constexpr int32 PriorityModifier = 0;
150→    const TCHAR* WorkingDir = nullptr;
151→
152→    BridgeProcessHandle = FPlatformProcess::CreateProc(
153→        PythonExe,
154→        *Args,
155→        bLaunchDetached,
156→        bLaunchHidden,
157→        bLaunchReallyHidden,
158→        &BridgeProcId,
159→        PriorityModifier,
160→        WorkingDir,
161→        nullptr  // PipeWriteChild
162→    );
163→
164→    if (BridgeProcessHandle.IsValid())
165→    {
166→        bBridgeProcessRunning = true;
167→        UE_LOG(LogTranslatorsBridge, Log,
168→            TEXT("Bridge process launched (PID %u): %s"), BridgeProcId, *ScriptPath);
169→    }
170→    else
171→    {
172→        UE_LOG(LogTranslatorsBridge, Error,
173→            TEXT("Failed to launch bridge process. Ensure 'python' is on PATH. Script: %s"), *ScriptPath);
174→    }
175→}
176→
177→void UBridgeEditorSubsystem::StopBridgeProcess()
178→{
179→    if (!bBridgeProcessRunning)
180→    {
181→        return;
182→    }
183→
184→    if (BridgeProcessHandle.IsValid() && FPlatformProcess::IsProcRunning(BridgeProcessHandle))
185→    {
186→        // Terminate with kill-tree enabled so child processes also stop
187→        FPlatformProcess::TerminateProc(BridgeProcessHandle, /* bKillTree */ true);
188→        UE_LOG(LogTranslatorsBridge, Log, TEXT("Bridge process terminated (PID %u)"), BridgeProcId);
189→    }
190→
191→    FPlatformProcess::CloseProc(BridgeProcessHandle);
192→    BridgeProcId = 0;
193→    bBridgeProcessRunning = false;
194→}
195→
196→bool UBridgeEditorSubsystem::IsBridgeProcessRunning() const
197→{
198→    if (!bBridgeProcessRunning)
199→    {
200→        return false;
201→    }
202→
203→    // Live check — if the process exited on its own, update our flag
204→    if (BridgeProcessHandle.IsValid() && !FPlatformProcess::IsProcRunning(BridgeProcessHandle))
205→    {
206→        // Process died externally; clean up state (mutable cast for bookkeeping)
207→        UBridgeEditorSubsystem* MutableThis = const_cast<UBridgeEditorSubsystem*>(this);
208→        FPlatformProcess::CloseProc(MutableThis->BridgeProcessHandle);
209→        MutableThis->BridgeProcId = 0;
210→        MutableThis->bBridgeProcessRunning = false;
211→        UE_LOG(LogTranslatorsBridge, Warning, TEXT("Bridge process (PID %u) exited unexpectedly"), BridgeProcId);
212→        return false;
213→    }
214→
215→    return true;
216→}
