131→void UW_TitleScreen::BuildWidgetTree()
132→{
133→    // Simple structure: Border (root, fills viewport) -> centered VerticalBox -> TextBlocks
134→    // Avoids CanvasPanel AutoSize issues that can collapse to zero
135→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
136→    BackgroundBorder->SetBrushColor(BackgroundColor);
137→    BackgroundBorder->SetHorizontalAlignment(HAlign_Center);
138→    BackgroundBorder->SetVerticalAlignment(VAlign_Center);
139→    BackgroundBorder->SetPadding(FMargin(40.0f));
140→    WidgetTree->RootWidget = BackgroundBorder;
141→
142→    // Content box (centered by border alignment)
143→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
144→    BackgroundBorder->AddChild(ContentBox);
145→
146→    // === Title: "The Translators" ===
147→    TitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TitleText"));
148→    TitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Title", "The Translators"));
149→    TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
150→    TitleText->SetJustification(ETextJustify::Center);
151→    TitleText->SetFont(FTranslatorsStyle::GetFont("Font.Title"));
152→
153→    UVerticalBoxSlot* TitleSlot = ContentBox->AddChildToVerticalBox(TitleText);
154→    if (TitleSlot)
155→    {
156→        TitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 12.0f));
157→        TitleSlot->SetHorizontalAlignment(HAlign_Center);
158→    }
159→
160→    // === Subtitle: "A cognitive profiling experience" ===
161→    SubtitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("SubtitleText"));
162→    SubtitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Subtitle", "A cognitive profiling experience"));
163→    SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
164→    SubtitleText->SetJustification(ETextJustify::Center);
165→    SubtitleText->SetFont(FTranslatorsStyle::GetFont("Font.Subtitle"));
166→
167→    UVerticalBoxSlot* SubtitleSlot = ContentBox->AddChildToVerticalBox(SubtitleText);
168→    if (SubtitleSlot)
169→    {
170→        SubtitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 60.0f));
171→        SubtitleSlot->SetHorizontalAlignment(HAlign_Center);
172→    }
173→
174→    // === Prompt: "Press ENTER to begin" ===
175→    PromptText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("PromptText"));
176→    PromptText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Prompt", "Press ENTER to begin"));
177→    PromptText->SetColorAndOpacity(FSlateColor(PromptColor));
178→    PromptText->SetJustification(ETextJustify::Center);
179→    PromptText->SetFont(FTranslatorsStyle::GetFont("Font.Body"));
180→
181→    UVerticalBoxSlot* PromptSlot = ContentBox->AddChildToVerticalBox(PromptText);
182→    if (PromptSlot)
183→    {
184→        PromptSlot->SetHorizontalAlignment(HAlign_Center);
185→    }
186→
187→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Built programmatic widget tree (Border root)"));
188→}
